from pathlib import Path
p=Path(__file__).resolve().parents[1]/'src/App.jsx'
s=p.read_text(encoding='utf-8')
def replace(a,b):
 global s
 if a not in s:raise ValueError('Missing edit anchor: '+a[:80])
 s=s.replace(a,b)
replace("import {SCENARIOS", "import {PollutionPanel} from './PollutionPanel.jsx';\nimport {isNoticeCurrent} from './notice.mjs';\nimport {SCENARIOS")
replace("['desk','Continuity desk',LayoutDashboard],", "['desk','Continuity desk',LayoutDashboard],['pollution','Pollution & GIS',FlaskConical],")
replace("export function Network({scenario='salinity',active=false})", "export function Network({scenario='salinity',active=false,multiplier=1})")
replace("<g stroke={active?'#3e8f68':'#a9bbb0'} strokeWidth=\"3\" fill=\"none\" strokeDasharray={active?'0':'7 5'}><path d=\"M115 90 L290 90 L500 65\"/><path d=\"M290 90 L500 180\"/><path d=\"M115 245 L290 245 L500 180\"/><path d=\"M290 245 L500 285\"/></g>","<g strokeWidth=\"3\" fill=\"none\"><path d=\"M191 90 L290 90 L290 133\" stroke={scenario==='storm'?'#b66b35':active?'#3e8f68':'#a9bbb0'} strokeDasharray={scenario==='storm'?'5 5':'0'}/><path d=\"M195 245 L290 245 L290 197\" stroke={scenario==='salinity'?'#b66b35':active?'#3e8f68':'#a9bbb0'} strokeDasharray={scenario==='salinity'?'5 5':'0'}/><path d=\"M362 160 L487 65 M362 160 L487 180 M362 160 L487 285\" stroke={active?'#3e8f68':'#a9bbb0'} strokeDasharray={active?'0':'7 5'}/></g>")
replace('1,200 L / day</text>', '{fmt(1200*multiplier)} L / day</text>')
replace('800 L / day</text>', '{fmt(800*multiplier)} L / day</text>')
replace('300 L / day · priority floor</text>', '{fmt(300*multiplier)} L / day · priority floor</text>')
replace('<path d="M290 197 L290 245" stroke="#3e8f68" strokeWidth="3"/><path d="M290 133 L290 90" stroke="#3e8f68" strokeWidth="3"/>','')
replace("const config=useMemo", "const [clockNow,setClockNow]=useState(Date.now());\n React.useEffect(()=>{const timer=setInterval(()=>setClockNow(Date.now()),15000);return()=>clearInterval(timer);},[]);\n const noticeValid=confirmed&&isNoticeCurrent(noticeTime,clockNow);\n const config=useMemo")
replace('function confirm(){setConfirmed(true);setNoticeTime(new Date().toISOString());', 'function confirm(){setClockNow(Date.now());setConfirmed(true);setNoticeTime(new Date().toISOString());')
replace('Coastal Bangladesh<small>', 'Bangladesh<small>')
replace('Coastal operations <ChevronRight', "{view==='pollution'?'Water evidence':'Coastal operations'} <ChevronRight")
replace('Scenario demo · no live alerts</span>', "{view==='pollution'?'Historical research data · no live alerts':'Scenario demo · no live alerts'}</span>")
replace("<h1>{view==='desk'?", "<h1>{view==='pollution'?'Water quality, grounded in evidence.':view==='desk'?")
replace("<p>{view==='desk'?'Climate disruption", "<p>{view==='pollution'?'Measured conditions → targeted investigation → verified response.':view==='desk'?'Climate disruption")
replace('<div className="scenario-switch" aria-label="Select hazard scenario">', "{view!=='pollution'&&<div className=\"scenario-switch\" aria-label=\"Select hazard scenario\">")
replace("</button>})}</div>\n {view==='desk'", "</button>})}</div>}\n {view==='pollution'&&<PollutionPanel/>}\n {view==='desk'")
replace('<Network scenario={scenario} active={computed}/>', '<Network scenario={scenario} active={computed} multiplier={multiplier}/><div className="network-mobile"><strong>Pooled usable reserve: {fmt(config.initial)} L</strong><span>Pump: {scenario===\'storm\'?\'offline / excluded\':\'available in scenario\'}</span><span>Pond: {scenario===\'salinity\'?\'held / excluded\':\'available in scenario\'}</span>{config.areas.map((a,i)=><span key={a}>{a}: {fmt(config.demands[i]*multiplier)} L / day</span>)}</div>')
replace("{confirmed?<><div className=\"notice-state\">", "{noticeValid?<><div className=\"notice-state\">")
replace("{bn?'এখনও নিশ্চিত করা হয়নি':'No confirmed notice yet'}", "{confirmed?(bn?'বিজ্ঞপ্তির মেয়াদ শেষ':'Notice expired'):(bn?'এখনও নিশ্চিত করা হয়নি':'No confirmed notice yet')}")
replace('disabled={!confirmed} onClick={()=>window.print()}', 'disabled={!noticeValid} onClick={()=>window.print()}')
replace('<g stroke="#e1e7df">{[30,85,140]', '<g fill="#52675f" fontSize="10"><text x="2" y="34">{fmt(max)}</text><text x="2" y="89">{fmt(max/2)}</text><text x="15" y="144">0</text></g><g stroke="#e1e7df">{[30,85,140]')
replace('<span>Fictional service network. Measured claims require a field pilot.</span>', "<span>{view==='pollution'?'Published historical samples. Current conditions require fresh measurements.':'Fictional service network. Measured claims require a field pilot.'}</span>")
p.write_text(s,encoding='utf-8')
css=p.parent/'styles.css';css.write_text(css.read_text(encoding='utf-8')+'\n.network-mobile{display:none}@media(max-width:700px){.network-panel .network{display:none}.network-mobile{display:flex;flex-direction:column;gap:12px;padding:20px;background:#edf3e8;font-size:12px}.network-mobile strong{padding-bottom:8px;border-bottom:1px solid #cad9c6}}\n',encoding='utf-8')
print('Integrated pollution module and confirmed review fixes.')
